function loadOrchestrations() {
  try {
    if (fs.existsSync(ORCHESTRATIONS_PATH)) return JSON.parse(fs.readFileSync(ORCHESTRATIONS_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveOrchestrations(list) {
  fs.writeFileSync(ORCHESTRATIONS_PATH, JSON.stringify(list, null, 2));
}

