app.post('/api/orchestrations', (req, res) => {
  const { id, name, nodes, edges } = req.body;
  if (!name || !Array.isArray(nodes) || !Array.isArray(edges)) {
    return res.status(400).json({ error: 'name, nodes, edges required' });
  }
  const list = loadOrchestrations();
  const now = new Date().toISOString();
  const orcId = id || genId();
  const idx = list.findIndex(o => o.id === orcId);
  const orc = { id: orcId, name, nodes, edges, updatedAt: now, createdAt: now };
  if (idx >= 0) { orc.createdAt = list[idx].createdAt; list[idx] = orc; }
  else list.unshift(orc);
  saveOrchestrations(list);
  res.json({ id: orcId });
});

