      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
    } else if (code !== 0 && !fullOutput.trim()) {
      send({ type: 'error', error: `Process exited with code ${code}` });
    } else {
      send({ type: 'done', output: fullOutput.trim() });
    }
    res.end();
  });

  proc.on('error', (err) => {
    clearTimeout(timer);
    send({ type: 'error', error: err.message });
    res.end();
  });

  proc.stdin.write(fullPrompt, 'utf8');
  proc.stdin.end();

  // Handle client disconnect — kill the process
  req.on('close', () => {
    if (!proc.killed) {
      clearTimeout(timer);
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 3000);
    }
  });
});

