  if (!fs.existsSync(filePath)) return res.status(404).json({ error: 'Not found' });
  res.json({ slug, content: fs.readFileSync(filePath, 'utf-8') });
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

